mapper.select:
select u.id, u.day_matter_id, u.user_id, m.day_name, r.user_name, r.user_code from mes_msg_day_matter_user u left join mes_msg_day_matter m on u.day_matter_id = m.id on m.deleted_flag = '0' left join mes_msg_user r on u.user_id = r.id on r.deleted_flag = '0'
u.deleted_flag = '0'
and u.user_id = #{param.userId}
and u.day_matter_id = #{param.dayMatterId}
order by u.update_time desc
